package com.specialattacktimers;

import java.awt.Color;
import java.time.Duration;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * InfoBox that displays the surge potion cooldown timer.
 * Shows "Surge Cooldown" on hover.
 */
public class SurgePotionInfoBox extends InfoBox
{
	private final SpecialAttackTimersPlugin plugin;
	private final SpecialAttackTimersConfig config;

	public SurgePotionInfoBox(SpecialAttackTimersPlugin plugin, SpecialAttackTimersConfig config)
	{
		super(null, plugin);
		this.plugin = plugin;
		this.config = config;
	}

	@Override
	public String getText()
	{
		Duration remaining = plugin.getSurgeCooldownRemaining();
		long totalMillis = remaining.toMillis();

		switch (config.surgeDisplayFormat())
		{
			case SECONDS:
				// Minutes:seconds format (e.g. 4:30) using integer division like RuneLite
				int totalSeconds = (int) (totalMillis / 1000);
				int minutes = totalSeconds / 60;
				int seconds = totalSeconds % 60;
				return String.format("%d:%02d", minutes, seconds);
			case DECIMALS:
				// Minutes:seconds with decimal (e.g. 4:29.4)
				double totalSecondsDecimal = totalMillis / 1000.0;
				int mins = (int) (totalSecondsDecimal / 60);
				double secs = totalSecondsDecimal % 60;
				return String.format("%d:%04.1f", mins, secs);
			case TICKS:
			default:
				// Convert milliseconds back to ticks for display
				return String.valueOf((int) (totalMillis / 600));
		}
	}

	@Override
	public Color getTextColor()
	{
		if (plugin.isSurgeCooldownPaused())
		{
			return config.surgePausedColor();
		}
		Duration remaining = plugin.getSurgeCooldownRemaining();
		int threshold = config.surgeExpiringThreshold();
		if (threshold > 0 && remaining.getSeconds() < threshold)
		{
			return config.surgeExpiringColor();
		}
		return config.surgeColor();
	}

	@Override
	public boolean render()
	{
		// Only render if surge cooldown is active
		Duration remaining = plugin.getSurgeCooldownRemaining();
		return !remaining.isZero() && !remaining.isNegative();
	}

	@Override
	public String getTooltip()
	{
		return "Surge Cooldown";
	}
}

package com.specialattacktimers;

import java.awt.Color;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("specialattacktimers")
public interface SpecialAttackTimersConfig extends Config
{
	@Getter
	@RequiredArgsConstructor
	enum DisplayFormat
	{
		TICKS("Ticks"),
		SECONDS("Seconds"),
		DECIMALS("Decimals");

		private final String name;

		@Override
		public String toString()
		{
			return name;
		}
	}

	@ConfigSection(
		name = "Display",
		description = "Overlay display settings",
		position = 0
	)
	String displaySection = "display";

	@ConfigItem(
		keyName = "showInfoBox",
		name = "Show Infobox",
		description = "Show the special attack timer infobox",
		position = 1,
		section = displaySection
	)
	default boolean showInfoBox()
	{
		return true;
	}

	@ConfigItem(
		keyName = "transparentInfoBox",
		name = "Transparent Infobox",
		description = "Show only the timer number, with no icon or background.",
		position = 2,
		section = displaySection
	)
	default boolean transparentInfoBox()
	{
		return false;
	}

	@Range(min = 8, max = 48)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "transparentFontSize",
		name = "Transparent Font Size",
		description = "Font size of the Transparent Infobox timer.",
		position = 3,
		section = displaySection
	)
	default int transparentFontSize()
	{
		return 16;
	}

	@ConfigItem(
		keyName = "displayFormat",
		name = "Display Format",
		description = "Ticks (game ticks), Seconds (whole), or Decimals (e.g. 29.4s)",
		position = 4,
		section = displaySection
	)
	default DisplayFormat displayFormat()
	{
		return DisplayFormat.TICKS;
	}

	@ConfigItem(
		keyName = "showCircularOverlay",
		name = "Show Circular Overlay",
		description = "Show circular progress indicator on the spec orb (like Regeneration Meter)",
		position = 5,
		section = displaySection
	)
	default boolean showCircularOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTimeToFullTooltip",
		name = "Time to Full Tooltip",
		description = "Show a \"Time to full\" tooltip when hovering the special attack orb",
		position = 6,
		section = displaySection
	)
	default boolean showTimeToFullTooltip()
	{
		return false;
	}

	@ConfigItem(
		keyName = "timeToFullFormat",
		name = "Time to Full Format",
		description = "Ticks (game ticks), Seconds (whole), or Decimals (e.g. 29.4s)",
		position = 7,
		section = displaySection
	)
	default DisplayFormat timeToFullFormat()
	{
		return DisplayFormat.SECONDS;
	}

	@ConfigSection(
		name = "Surge Potion Timer",
		description = "Surge potion cooldown timer settings",
		position = 5
	)
	String surgeSection = "surge";

	@ConfigItem(
		keyName = "showSurgeInfoBox",
		name = "Show Surge Timer",
		description = "Show the surge potion cooldown timer infobox",
		position = 6,
		section = surgeSection
	)
	default boolean showSurgeInfoBox()
	{
		return true;
	}

	@ConfigItem(
		keyName = "surgeDisplayFormat",
		name = "Surge Display Format",
		description = "Ticks (game ticks), Seconds (whole), or Decimals (e.g. 29.4s)",
		position = 7,
		section = surgeSection
	)
	default DisplayFormat surgeDisplayFormat()
	{
		return DisplayFormat.SECONDS;
	}

	@Range(min = 0, max = 300)
	@ConfigItem(
		keyName = "surgeExpiringThreshold",
		name = "Surge Expiring Threshold",
		description = "Seconds remaining to change the surge timer color (0 to disable)",
		position = 8,
		section = surgeSection
	)
	default int surgeExpiringThreshold()
	{
		return 30;
	}

	@ConfigSection(
		name = "Colors",
		description = "Color settings for the overlay",
		position = 10
	)
	String colorSection = "colors";

	@Alpha
	@ConfigItem(
		keyName = "activeColor",
		name = "Infobox Color",
		description = "Color for the spec regen timer infobox text",
		position = 11,
		section = colorSection
	)
	default Color activeColor()
	{
		return new Color(255, 255, 255, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "circleColor",
		name = "Circle Overlay Color",
		description = "Color for the circular progress indicator on the spec orb",
		position = 12,
		section = colorSection
	)
	default Color circleColor()
	{
		return new Color(0, 255, 255, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "surgeColor",
		name = "Surge Active Color",
		description = "Color for the surge potion cooldown timer when active (unpaused)",
		position = 13,
		section = colorSection
	)
	default Color surgeColor()
	{
		return new Color(255, 255, 255, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "surgePausedColor",
		name = "Surge Paused Color",
		description = "Color for the surge potion cooldown timer when paused (between waves/rooms)",
		position = 14,
		section = colorSection
	)
	default Color surgePausedColor()
	{
		return new Color(255, 165, 0, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "surgeExpiringColor",
		name = "Surge Expiring Color",
		description = "Color for the surge potion cooldown timer when under the expiring threshold",
		position = 15,
		section = colorSection
	)
	default Color surgeExpiringColor()
	{
		return new Color(255, 0, 0, 255);
	}

	@ConfigSection(
		name = "Instructions",
		description = "Important setup instructions",
		position = 20,
		closedByDefault = false
	)
	String instructionsSection = "instructions";

	@ConfigItem(
		keyName = "instructionsText",
		name = "",
		description = "",
		position = 21,
		section = instructionsSection
	)
	default String instructionsText()
	{
		return "\nPlease disable \"Show spec. attack regen\" in the \"Regeneration Meter\" plugin.\n\n"
			+ "Optionally, if you're using the Surge Potion timer, disable \"Surge potion timer\" in \"Timers & Buffs\".\n";
	}
}

package com.specialattacktimers;

import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * Standalone overlay that shows only the spec regen timer number, with no icon or background.
 * Used in place of the infobox when the "Transparent Infobox" option is enabled, since
 * RuneLite applies the global overlay background color to every infobox.
 *
 * Uses the same font and text outline settings as RuneLite infoboxes, at the configured
 * font size. Movable with Alt-drag.
 */
public class SpecialAttackTimersTextOverlay extends Overlay
{
	private final Client client;
	private final SpecialAttackTimersPlugin plugin;
	private final SpecialAttackTimersConfig config;
	private final RuneLiteConfig runeLiteConfig;
	private final TextComponent textComponent = new TextComponent();

	@Inject
	public SpecialAttackTimersTextOverlay(Client client, SpecialAttackTimersPlugin plugin,
		SpecialAttackTimersConfig config, RuneLiteConfig runeLiteConfig)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.runeLiteConfig = runeLiteConfig;

		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);

		// Don't allow snapping into overlay corners. The minimap sits in the top-right snap corner,
		// whose drop area grows to cover the whole minimap, so a snappable overlay can't be placed
		// on the spec orb. Non-snappable overlays always stay exactly where they are dropped.
		setSnappable(false);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}

		// Only shown in place of the infobox when transparent mode is enabled
		if (!config.showInfoBox() || !config.transparentInfoBox())
		{
			return null;
		}

		// Don't render if spec is full or between waves/delves (timer paused)
		if (plugin.isSpecFull() || plugin.isBetweenWaves())
		{
			return null;
		}

		String text = plugin.getRegenTimerText();
		Font font = runeLiteConfig.infoboxFont().getFont().deriveFont((float) config.transparentFontSize());
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();

		// Use a fixed width (the widest text the current format can show) and center the text in it,
		// like the regular infobox, so the number doesn't shift as it counts down
		int boxWidth = getMaxTextWidth(metrics);
		int x = (boxWidth - metrics.stringWidth(text)) / 2;

		textComponent.setText(text);
		textComponent.setFont(font);
		textComponent.setColor(config.activeColor());
		textComponent.setOutline(runeLiteConfig.infoBoxTextOutline());
		textComponent.setPosition(x, metrics.getAscent());
		textComponent.render(graphics);

		return new Dimension(boxWidth, metrics.getHeight());
	}

	/**
	 * Gets the width of the widest text the timer can show in the current display format:
	 * two digits for ticks/seconds (max 50 ticks or 30 seconds), or "00.0s" for decimals.
	 * Uses the widest digit so the width never changes while counting down.
	 */
	private int getMaxTextWidth(FontMetrics metrics)
	{
		int maxDigitWidth = 0;
		for (char digit = '0'; digit <= '9'; digit++)
		{
			maxDigitWidth = Math.max(maxDigitWidth, metrics.charWidth(digit));
		}

		if (config.displayFormat() == SpecialAttackTimersConfig.DisplayFormat.DECIMALS)
		{
			return 3 * maxDigitWidth + metrics.charWidth('.') + metrics.charWidth('s');
		}
		return 2 * maxDigitWidth;
	}
}

